import { mkdir, readFile, readdir, unlink, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import openapiTS, { astToString } from 'openapi-typescript';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const banner =
  '/** Generated by cargo xtask codegen from Rust. Do not edit. */\n';

export async function updateGeneratedFiles(directory, files, check) {
  const existing = await readdir(directory).catch((error) => {
    if (error.code === 'ENOENT') return [];
    throw error;
  });
  const stale = existing.filter((name) => !Object.hasOwn(files, name));
  for (const [name, content] of Object.entries(files)) {
    const previous = await readFile(resolve(directory, name), 'utf8').catch(
      (error) => {
        if (error.code === 'ENOENT') return null;
        throw error;
      },
    );
    if (previous !== content) stale.push(name);
  }
  if (check) {
    if (stale.length)
      throw new Error(
        `Generated contracts differ: ${stale.join(', ')}. Run cargo xtask codegen.`,
      );
    return;
  }
  await mkdir(directory, { recursive: true });
  for (const name of existing.filter((name) => !Object.hasOwn(files, name))) {
    await unlink(resolve(directory, name));
  }
  for (const [name, content] of Object.entries(files)) {
    await writeFile(resolve(directory, name), content);
  }
}

/** Mechanically translate named documents; no adapter names or type mappings. */
export async function renderDocuments(documents) {
  const files = {
    'manifest.json':
      JSON.stringify(Object.keys(documents).sort(), null, 2) + '\n',
  };
  for (const [name, document] of Object.entries(documents).sort(([a], [b]) =>
    a.localeCompare(b),
  )) {
    if (!/^[a-z][a-z0-9-]*$/.test(name))
      throw new Error(`Invalid contract module name: ${name}`);
    files[`${name}.openapi.json`] = JSON.stringify(document, null, 2) + '\n';
    files[`${name}.generated.ts`] =
      banner +
      astToString(
        await openapiTS(document, {
          rootTypes: true,
          rootTypesNoSchemaPrefix: true,
          rootTypesKeepCasing: true,
          // Settings are request bodies: a field serde defaults may be omitted.
          defaultNonNullable: false,
        }),
      );
  }
  return files;
}

/**
 * Server-known values as `export const` declarations, `as const` so each
 * value is also its own literal type; the names must be TypeScript-safe.
 */
export function renderConstants(constants) {
  return (
    banner +
    Object.entries(constants)
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([name, value]) => {
        if (!/^[a-z][A-Za-z0-9]*$/.test(name))
          throw new Error(`Invalid constant name: ${name}`);
        return `export const ${name} = ${JSON.stringify(value, null, 2)} as const;\n`;
      })
      .join('\n')
  );
}

/**
 * Writes (or with `check` compares) the generated files from `input`, the
 * exporter's JSON (`documents`, `constants`, `fixtures`), which
 * `cargo xtask codegen` produces and passes in.
 */
async function generate(input, check) {
  const { documents, constants, fixtures } = JSON.parse(
    await readFile(input, 'utf8'),
  );
  const files = await renderDocuments(documents);
  files['constants.generated.ts'] = renderConstants(constants);
  files['fixtures.json'] = JSON.stringify(fixtures, null, 2) + '\n';
  await updateGeneratedFiles(
    resolve(root, 'packages/contracts/generated'),
    files,
    check,
  );
}

if (
  process.argv[1] &&
  resolve(process.argv[1]) === fileURLToPath(import.meta.url)
) {
  const args = process.argv.slice(2);
  const check = args[0] === '--check';
  const [input, ...rest] = check ? args.slice(1) : args;
  if (!input || rest.length) {
    console.error(
      "Usage: codegen.mjs [--check] EXPORT.json, the Rust exporter's output. Run `cargo xtask codegen [--check]` from the repository root instead.",
    );
    process.exit(2);
  }
  await generate(input, check);
}
